settings.custom_code:
{%- assign wt = nil -%}

{%- if product and product.metafields.custom.never_compromise_weight_table.value -%}
  {%- assign wt = product.metafields.custom.never_compromise_weight_table.value -%}
{%- elsif page and page.metafields.custom.never_compromise_weight_table.value -%}
  {%- assign wt = page.metafields.custom.never_compromise_weight_table.value -%}
{%- endif -%}

{% if wt %}
  <style>
    .wt-wrapper { overflow-x: auto; margin-top: 20px; }
    .wt-table { width: 100%; border-collapse: collapse; font-size: 14px; min-width: 760px; }
    .wt-table th { background:#000; color:#fff; padding:10px; text-align:left; font-weight:600; white-space:nowrap; }
    .wt-table td { padding:10px; border-bottom:1px solid #e5e5e5; vertical-align:middle; white-space:nowrap; }
    .wt-table td:first-child { font-weight:600; }
    .wt-table tr:nth-child(even) { background:#f7f7f7; }
    .wt-table tr:hover { background:#f0f0f0; }
    .wt-img { display:flex; align-items:center; }
    .wt-img img { width:44px; height:auto !important; object-fit:contain !important; display:block; }
  </style>

  <div class="wt-wrapper">
    <table class="wt-table">
      <thead>
        <tr>
          <th>Length</th>
          {% for col in wt.columns.value %}
            <th>{{ col.length }}</th>
          {% endfor %}
        </tr>
      </thead>

      <tbody>
        <tr>
          <td>Sole Weight</td>
          {% for col in wt.columns.value %}
            <td>{{ col.sole_weight }}</td>
          {% endfor %}
        </tr>

        <tr>
          <td>Weight</td>
          {% for col in wt.columns.value %}
            <td>
              {% if col.sole_weight_image %}
                <span class="wt-img">
                  {{ col.sole_weight_image | image_url: width: 160 | image_tag: loading: 'lazy', alt: col.sole_weight_material }}
                </span>
              {% endif %}
            </td>
          {% endfor %}
        </tr>

        <tr>
          <td>Sole Weight Material</td>
          {% for col in wt.columns.value %}
            <td>{{ col.sole_weight_material }}</td>
          {% endfor %}
        </tr>

        <tr>
          <td>Total Head Weight</td>
          {% for col in wt.columns.value %}
            <td>{{ col.total_head_weight }}</td>
          {% endfor %}
        </tr>
      </tbody>
    </table>
  </div>
{% endif %}

{% assign grips = page.metafields.custom.never_compromise_grip.value %}

{% if grips %}
  <style>
    .nc-grip-section {
      background: #000;
      color: #fff;
      padding: 70px 20px;
    }

    .nc-grip {
      margin-bottom: 70px;
    }

    .nc-grip__inner {
      max-width: 1100px;
      margin: 0 auto;
    }

    .nc-grip__header {
      text-align: center;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: .06em;
      margin-bottom: 28px;
      font-size: 20px;
      color: #fff;
    }

    .nc-grip__images {
      display: grid;
      gap: 28px;
      justify-items: center;
    }

    /* Image 1 (Primary) */
    .nc-grip__images img:first-child {
      width: 100%;
      max-width: 900px;
      height: auto !important;
      object-fit: contain !important;
      display: block;
    }

    /* Image 2 (70% smaller = 30% width) */
    .nc-grip__images img:last-child {
      width: 30%;
      max-width: 270px;
      height: auto !important;
      object-fit: contain !important;
      display: block;
    }

    .nc-grip__footnote {
      margin-top: 26px;
      text-align: center;
      font-size: 15px;
      line-height: 1.6;
      color: #ddd;
      max-width: 760px;
      margin-left: auto;
      margin-right: auto;
    }

    .nc-grip:not(:last-child) {
      border-bottom: 1px solid rgba(255,255,255,.08);
      padding-bottom: 70px;
    }

    /* Mobile adjustments */
    @media (max-width: 768px) {
      .nc-grip-section {
        padding: 50px 16px;
      }

      .nc-grip__header {
        font-size: 18px;
      }

      .nc-grip__images img:first-child {
        max-width: 100%;
      }

      .nc-grip__images img:last-child {
        width: 50%; /* slightly larger on mobile for visibility */
        max-width: 100%;
      }
    }
  </style>

  <div class="nc-grip-section">
    {% for item in grips %}
      <section class="nc-grip">
        <div class="nc-grip__inner">

          {% if item.header != blank %}
            <div class="nc-grip__header">
              {{ item.header }}
            </div>
          {% endif %}

          <div class="nc-grip__images">
            {% if item.image_1 %}
              {{ item.image_1 | image_url: width: 1600 | image_tag: loading: 'lazy', alt: item.header }}
            {% endif %}

            {% if item.image_2 %}
              {{ item.image_2 | image_url: width: 1600 | image_tag: loading: 'lazy', alt: item.header }}
            {% endif %}
          </div>

          {% if item.footnote != blank %}
            <div class="nc-grip__footnote">
              {{ item.footnote }}
            </div>
          {% endif %}

        </div>
      </section>
    {% endfor %}
  </div>
{% endif %}
